import java.util.ArrayList;
import java.util.List;

public class ContravarianceDemo {
    // Consumer Sink: fills destination with generated sequence numbers
    public static void generateMultiples(int count, int multiplier, List<? super Integer> sink) {
        for (int i = 1; i <= count; i++) {
            // Safe writing: Integer is compatible with ? super Integer
            sink.add(i * multiplier);
        }
    }

    public static void main(String[] args) {
        List<Integer> integerList = new ArrayList<>();
        List<Number> numberList = new ArrayList<>();
        List<Object> objectList = new ArrayList<>();

        // The exact same method writes into all three collections seamlessly!
        generateMultiples(3, 5, integerList); // List<Integer>
        generateMultiples(3, 10, numberList); // List<Number>
        generateMultiples(3, 100, objectList); // List<Object>

        System.out.println("Integer sink: " + integerList); // [5, 10, 15]
        System.out.println("Number sink:  " + numberList);  // [10, 20, 30]
        System.out.println("Object sink:  " + objectList);  // [100, 200, 300]
    }
}
// Expected Output:
// Integer sink: [5, 10, 15]
// Number sink:  [10, 20, 30]
// Object sink:  [100, 200, 300]

