import java.util.ArrayList;
import java.util.List;

public class StringAccumulator {
    public static void collectTags(String[] tags, List<? super String> destination) {
        if (tags == null || destination == null) return;
        for (String tag : tags) {
            if (tag != null && !tag.isBlank()) {
                destination.add(tag.trim().toLowerCase());
            }
        }
    }

    public static void main(String[] args) {
        String[] rawTags = {" Java ", " Collections ", ""};

        List<String> strSink = new ArrayList<>();
        List<Object> objSink = new ArrayList<>();

        collectTags(rawTags, strSink);
        collectTags(rawTags, objSink);

        System.out.println("strSink size: " + strSink.size() + ", items: " + strSink);
        System.out.println("objSink size: " + objSink.size() + ", items: " + objSink);
    }
}

