import java.util.List;
import java.util.ArrayList;

public class IngestionGuard {
    public static void addIfAbsent(List<? super String> sink, List<?> existing, String item) {
        if (sink == null || existing == null || item == null) return;
        if (!existing.contains(item)) {
            sink.add(item);
        }
    }

    public static void main(String[] args) {
        List<Object> sink = new ArrayList<>();
        List<String> current = List.of("alpha", "beta");
        addIfAbsent(sink, current, "beta");
        addIfAbsent(sink, current, "gamma");
        System.out.println(sink);
    }
}

